import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty for no overdue invoices', () => {
  const result = overdueInvoices([], '2026-10-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const result = overdueInvoices([inv.value], '2026-10-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  inv = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(inv);
  inv = recordPayment(inv, { amount: totals.total, date: '2026-10-02' }).value;

  const result = overdueInvoices([inv], '2026-10-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices past due', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(issued);

  const result = overdueInvoices([issued], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-002');
  assert.equal(result[0].dueDate, '2026-10-15');
  assert.equal(result[0].daysOverdue, 5);
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices includes partially_paid invoices past due', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  inv = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(inv);
  const paymentAmount = Math.floor(totals.total / 2);
  inv = recordPayment(inv, { amount: paymentAmount, date: '2026-10-02' }).value;

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - paymentAmount);
});

test('overdueInvoices excludes invoices on due date', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = overdueInvoices([issued], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices before due date', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = overdueInvoices([issued], '2026-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;

  const result = overdueInvoices([issued1, issued2, issued3], '2026-10-31');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].daysOverdue, 46);
  assert.equal(result[1].number, 'INV-2026-0002');
  assert.equal(result[1].daysOverdue, 32);
  assert.equal(result[2].number, 'INV-2026-0003');
  assert.equal(result[2].daysOverdue, 16);
});

test('overdueInvoices with mixed statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  inv2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  const totals = invoiceTotals(inv2);
  inv2 = recordPayment(inv2, { amount: totals.total, date: '2026-10-02' }).value;

  const result = overdueInvoices([issued1, inv2], '2026-10-31');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = overdueInvoices([issued], '2026-11-10');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2026-10-31');
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices with no invoices returns empty array', () => {
  const result = overdueInvoices([], '2026-10-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices with complex scenario', () => {
  const invoices = [];

  // Draft invoice - should be excluded
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  invoices.push(draft.value);

  // Issued invoice that is overdue
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;
  invoices.push(issued1);

  // Issued invoice not yet due
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;
  invoices.push(issued2);

  // Partially paid invoice that is overdue
  let inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
    terms: 'NET14',
  });
  inv3 = issueInvoice(inv3.value, ['INV-2026-0002']).value;
  const totals3 = invoiceTotals(inv3);
  inv3 = recordPayment(inv3, { amount: Math.floor(totals3.total / 2), date: '2026-10-02' }).value;
  invoices.push(inv3);

  // Paid invoice - should be excluded
  let inv4 = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-08-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  inv4 = issueInvoice(inv4.value, ['INV-2026-0003']).value;
  const totals4 = invoiceTotals(inv4);
  inv4 = recordPayment(inv4, { amount: totals4.total, date: '2026-09-01' }).value;
  invoices.push(inv4);

  const result = overdueInvoices(invoices, '2026-10-31');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0003');
  assert.equal(result[2].number, 'INV-2026-0002');
  assert(result[0].daysOverdue > result[1].daysOverdue);
  assert(result[1].daysOverdue > result[2].daysOverdue);
});

test('overdueInvoices calculates due amount correctly', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  inv = issueInvoice(inv.value, []).value;
  const totals = invoiceTotals(inv);
  const paymentAmount = 10000;
  inv = recordPayment(inv, { amount: paymentAmount, date: '2026-10-02' }).value;

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - paymentAmount);
});

test('overdueInvoices with EOM terms', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  const issued = issueInvoice(inv.value, []).value;

  const result = overdueInvoices([issued], '2026-11-02');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2026-10-31');
  assert.equal(result[0].daysOverdue, 2);
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']).value;

  const result = overdueInvoices([issued1, issued2], '2026-10-31');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

