    expected0VAT = 0;

  for (const line of issued.lines) {
    const base = lineTotal(line) - lineDiscount(line);
    const vat = lineVAT(line);
    if (line.vatRate === 21) {
      expected21Base += base;
      expected21VAT += vat;
    } else if (line.vatRate === 9) {
      expected9Base += base;
      expected9VAT += vat;
    } else {
      expected0Base += base;
      expected0VAT += vat;
    }
  }

