import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const PRODUCTS = JSON.parse(readFileSync(new URL('../data/catalogue.json', import.meta.url), 'utf8'));

/**
 * All products: { sku, name, unitPrice (cents, without VAT), vatRate (percent) }.
 * @returns {Array<{ sku: string, name: string, unitPrice: number, vatRate: number }>}
 */
export function listProducts() {
  return PRODUCTS.map((p) => ({ ...p }));
}

/**
 * One product by SKU.
 * @param {string} sku
 */
export function getProduct(sku) {
  const p = PRODUCTS.find((x) => x.sku === sku);
  return p ? ok({ ...p }) : fail('UNKNOWN_SKU');
}

