  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);

  // Calculate expected values
  let expected21Base = 0,
    expected21VAT = 0;
  let expected9Base = 0,
    expected9VAT = 0;
  let expected0Base = 0,
    expected0VAT = 0;

  for (const line of issued.lines) {
    const base = lineTotal(line) - lineDiscount(line);
    const vat = lineVAT(line);
    if (line.vatRate === 21) {
      expected21Base += base;
      expected21VAT += vat;
    } else if (line.vatRate === 9) {
      expected9Base += base;
      expected9VAT += vat;
    } else {
      expected0Base += base;
      expected0VAT += vat;
    }
  }

  assert.equal(result[0].base, expected21Base);
  assert.equal(result[0].vat, expected21VAT);
  assert.equal(result[1].base, expected9Base);
  assert.equal(result[1].vat, expected9VAT);
  assert.equal(result[2].base, expected0Base);
  assert.equal(result[2].vat, expected0VAT);
});

test('vatSummary with mixed invoice statuses', () => {
  // Draft
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  // Issued
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued = issueInvoice(inv2.value, []).value;

  // Paid
  let inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  inv3 = issueInvoice(inv3.value, ['INV-2026-0001']).value;
  const totals = invoiceTotals(inv3);
  inv3 = recordPayment(inv3, { amount: totals.total, date: '2026-10-10' }).value;

  const result = vatSummary([draft.value, issued, inv3]);
  assert.equal(result.length, 1);

  const expectedBase = (lineTotal(issued.lines[0]) - lineDiscount(issued.lines[0])) +
                       (lineTotal(inv3.lines[0]) - lineDiscount(inv3.lines[0]));
  const expectedVAT = lineVAT(issued.lines[0]) + lineVAT(inv3.lines[0]);

  assert.equal(result[0].base, expectedBase);
  assert.equal(result[0].vat, expectedVAT);
});
